<script type="text/javascript">

	function adsub() 
		{
			if (window.status.indexOf('go to') == 0) 
				{
					dummyimage = new Image();
					dummyimage.src = 'http://www.niche-mania.com/AdTracker.php?' + 'dmn=<?=$_SERVER["HTTP_HOST"];?>' + '&' + 'src=' + document.location + '&' + 'tgt=' + window.status.substring(6) + '&' + 'wdh=' + event.srcElement.width + '&' + 'hgt=' + event.srcElement.height + '&' + 'typ=regular';
				}
	
			if (window.status.indexOf('View ads about') == 0) 
				{
					dummyimage = new Image();
					dummyimage.src = 'http://www.niche-mania.com/AdTracker.php?' + 'dmn=<?=$_SERVER["HTTP_HOST"];?>' + '&' + 'src=' + document.location + '&' + 'tgt=' + window.status.substring(15) + '&' + 'wdh=' + event.srcElement.width + '&' + 'hgt=' + event.srcElement.height + '&' + 'typ=link';
				}
		}

	function shsub() 
		{
			dummyimage = new Image();
			dummyimage.src = 'http://www.niche-mania.com/AdTracker.php?' + 'dmn=<?=$_SERVER["HTTP_HOST"];?>' + '&' + 'src=' + document.location + '&' + 'tgt=' + event.srcElement.form.q.value + '&' + 'typ=search';
		}

	var iframes;
	
	iframes = document.getElementsByTagName("iframe");
	
	for (var i = 0; i < iframes.length; i++) 
		{
			if(iframes[i].src.indexOf('googlesyndication') > -1) 
				{
					iframes[i].attachEvent("onfocus", adsub);
				}
		}

	var forms;
	
	forms = document.getElementsByTagName("form");
	
	for (var i = 0; i < forms.length; i++) 
		{
			if(forms[i].action == "http://www.google.com/custom") 
				{
					forms[i].sa.attachEvent("onclick", shsub);
				}
		}
</script>
